"use client";

import GitHubActivity, {
  type Contribution,
  type ContributionLevel,
  type RepoContribution,
} from "@/components/ui/github-activity";

const WEEKS = 53;
const ANCHOR = new Date("2025-12-27T00:00:00Z");

function pseudoCount(index: number) {
  const noise = Math.sin(index * 12.9898) * 43758.5453;
  const fraction = noise - Math.floor(noise);
  const weekday = index % 7;
  const weekendDrop = weekday === 0 || weekday === 6 ? 0.35 : 1;
  return Math.round(fraction ** 2 * 18 * weekendDrop);
}

function toLevel(count: number): ContributionLevel {
  if (count === 0) return 0;
  if (count < 3) return 1;
  if (count < 6) return 2;
  if (count < 10) return 3;
  return 4;
}

const contributions: Contribution[] = Array.from(
  { length: WEEKS * 7 },
  (_, i) => {
    const date = new Date(ANCHOR);
    date.setUTCDate(date.getUTCDate() - (WEEKS * 7 - 1 - i));
    const count = pseudoCount(i);
    return {
      date: date.toISOString().slice(0, 10),
      count,
      level: toLevel(count),
    };
  },
);

